async function trackContactClick\(profileId: string, contactType: 'whatsapp' | 'telegram' | 'email' | 'website'\) {
    try {
        await fetch\('/api/track-contact-click', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
